","import React, { useState, useEffect, useCallback } from "react";
import "./styles.css";

declare const window: Window & { g_ck?: string };

const API = "/api/x_2056099_indust_0/";

async function api(path: string, opts?: RequestInit) {
 const res = await fetch(API + path, {
 headers: {
 "Content-Type": "application/json",
 Accept: "application/json",
 "X-UserToken": window.g_ck || "",
 },
 ...opts,
 });
 return res.json();
}

function post(path: string, body: object) {
 return api(path, { method: "POST", body: JSON.stringify(body) });
}

interface ModalState {
 type: string;
 poId: string;
 label: string;
 matId?: string;
 matName?: string;
}

const STATUS_COLORS: Record<string, string> = {
 in_production: "ok",
 completed: "ok",
 reserved: "ok",
 scheduled: "ok",
 confirmed: "ok",
 feasible: "ok",
 material_check: "info",
 draft: "gray",
 shortage: "err",
 critical: "err",
 high: "warn",
 medium: "info",
 low: "gray",
 cancelled: "gray",
};

function Badge({ value }: { value: string }) {
 const cls = STATUS_COLORS[value] || "gray";
 const label = value ? value.replace(/_/g, " ") : "\u2014";
 return <span className={`badge ${cls}`}>{label}</span>;
}

function Stat({ val, label, color }: { val: number | string; label: string; color?: string }) {
 return (
 <div className="stat">
 <div className="val" style={color ? { color } : undefined}>{val}</div>
 <div className="lbl">{label}</div>
 </div>
 );
}

export default function App() {
 const [tab, setTab] = useState("home");
 const [sel, setSel] = useState<any>(null);
 const [modal, setModal] = useState<ModalState | null>(null);
 const [data, setData] = useState<any>({});
 const [loading, setLoading] = useState(true);
 const [msg, setMsg] = useState<{ type: string; text: string } | null>(null);
 const [qty, setQty] = useState("1");
 const [notes, setNotes] = useState("");

 const load = useCallback(() => {
 setLoading(true);
 setMsg(null);
 Promise.all([
 api("operator_api/summary"),
 api("operator_api/schedule-planner-data"),
 api("inventory_api/data"),
 api("alert_center_api/alerts"),
 api("dashboard_api/kpis"),
 ])
 .then(([summary, schedule, inventory, alerts, kpis]) => {
 setData({ summary, schedule, inventory, alerts, kpis });
 setLoading(false);
 })
 .catch(() => setLoading(false));
 }, []);

 useEffect(() => { load(); }, [load]);

 function doAction(endpoint: string, body: object, label: string) {
 setMsg(null);
 post("operator_api/" + endpoint, body).then((r: any) => {
 if (r.error || (r.result && r.result.error)) {
 setMsg({ type: "err", text: label + " failed: " + (r.error || r.result?.error || r.result?.message || "Unknown") });
 } else {
 setMsg({ type: "ok", text: label + " successful" });
 setModal(null);
 load();
 setSel(null);
 }
 });
 }

 const orders: any[] = (() => {
 try { const r = data.summary?.result; return Array.isArray(r?.production_orders) ? r.production_orders : Array.isArray(r?.orders) ? r.orders : Array.isArray(r) ? r : []; } catch { return []; }
 })();
 const scheds: any[] = (() => {
 try { const r = data.schedule?.result; return Array.isArray(r?.schedules) ? r.schedules : Array.isArray(r) ? r : []; } catch { return []; }
 })();
 const stocks: any[] = (() => {
 try { const r = data.inventory?.result; return Array.isArray(r?.inventory) ? r.inventory : Array.isArray(r?.stocks) ? r.stocks : Array.isArray(r) ? r : []; } catch { return []; }
 })();
 const alerts: any[] = (() => {
 try { const r = data.alerts?.result; return Array.isArray(r?.alerts) ? r.alerts : Array.isArray(r) ? r : []; } catch { return []; }
 })();

 function switchTab(t: string) { setTab(t); setSel(null); setMsg(null); }

 // ==================== HOME ====================
 function HomeTab() {
 const active = orders.filter(o => o.status === "in_production").length;
 const overdue = orders.filter(o => o.planned_end_date && o.planned_end_date < "2026-10-05").length;
 const hiPri = orders.filter(o => o.priority === "high" || o.priority === "critical").slice(0, 5);
 return (
 <div>
 <div className="stat-row"><Stat val={orders.length} label="Total Orders" /><Stat val={active} label="In Production" color="var(--ok)" /></div>
 <div className="stat-row"><Stat val={scheds.length} label="Schedules" /><Stat val={overdue} label="Overdue" color={overdue ? "var(--err)" : "var(--ok)"} /></div>
 <div className="stat-row"><Stat val={alerts.length} label="Alerts" /><Stat val={stocks.length} label="Stock Records" /></div>
 {hiPri.map((o, i) => (
 <div className="card" key={i} onClick={() => { setSel(o); setTab("orders"); }}>
 <h3>{o.number || o.production_order_number || "PO"}</h3>
 <div className="meta"><Badge value={o.status} /><Badge value={o.priority} /><span>Due: {(o.planned_end_date || "").substring(0, 10)}</span></div>
 </div>
 ))}
 </div>
 );
 }

 // ==================== ORDERS ====================
 function OrdersTab() {
 if (sel) return <OrderDetail />;
 return (
 <div>
 {orders.length === 0 ? <div className="empty">No production orders</div> : orders.map((o, i) => (
 <div className="card" key={i} onClick={() => { setSel(o); setMsg(null); }}>
 <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
 <h3>{o.number || o.production_order_number || "PO"}</h3>
 <Badge value={o.status} />
 </div>
 <div className="meta"><Badge value={o.priority} /><span>Qty: {o.quantity_planned || 1}</span><span>Due: {(o.planned_end_date || "").substring(0, 10)}</span></div>
 </div>
 ))}
 </div>
 );
 }

 // ==================== DETAIL ====================
 function OrderDetail() {
 if (!sel) return null;
 const st = sel.status;
 const poId = sel.sys_id || sel.production_order_id || "";
 const mats: any[] = sel.materials || sel.production_materials || [];
 return (
 <div>
 <div className="detail-section">
 <h4>Production Order</h4>
 <div className="detail-row"><span className="label">Number</span><span className="value">{sel.number || sel.production_order_number}</span></div>
 <div className="detail-row"><span className="label">Status</span><span className="value"><Badge value={st} /></span></div>
 <div className="detail-row"><span className="label">Priority</span><span className="value"><Badge value={sel.priority} /></span></div>
 <div className="detail-row"><span className="label">Planned</span><span className="value">{sel.quantity_planned || 1}</span></div>
 <div className="detail-row"><span className="label">Produced</span><span className="value">{sel.quantity_produced || 0}</span></div>
 <div className="detail-row"><span className="label">Remaining</span><span className="value">{sel.quantity_remaining || 0}</span></div>
 <div className="detail-row"><span className="label">Resource</span><span className="value">{sel.assigned_resource || sel.resource || "\u2014"}</span></div>
 <div className="detail-row"><span className="label">Deadline</span><span className="value">{(sel.planned_end_date || "").substring(0, 10)}</span></div>
 </div>
 {mats.length > 0 && (
 <div className="detail-section">
 <h4>Materials ({mats.length})</h4>
 {mats.map((m, i) => (
 <div key={i} style={{ padding: "8px 0", borderBottom: "1px solid #f1f3f5", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
 <div>
 <div style={{ fontSize: 13, fontWeight: 500 }}>{m.material || m.material_product || "Material"}</div>
 <div style={{ fontSize: 11, color: "var(--txt2)" }}>Req: {m.required_quantity || 1} | Res: {m.reserved_quantity || 0}</div>
 </div>
 <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
 <Badge value={m.status} />
 {st === "in_production" && (
 <button className="btn primary" style={{ padding: "6px 10px", fontSize: 11, minWidth: "auto" }}
 onClick={() => { setQty("1"); setModal({ type: "issue-material", poId, matId: m.sys_id || m.production_material_id, matName: m.material || m.material_product, label: "Issue Material" }); }}>
 Issue
 </button>
 )}
 </div>
 </div>
 ))}
 </div>
 )}
 <div className="actions">
 {(st === "material_check" || st === "materials_reserved" || st === "planned") && <button className="btn primary" onClick={() => setModal({ type: "start-production", poId, label: "Start Production" })}>Start</button>}
 {st === "in_production" && <button className="btn success" onClick={() => { setQty("1"); setNotes(""); setModal({ type: "record-production", poId, label: "Record Production" }); }}>Record</button>}
 {st === "in_production" && <button className="btn primary" onClick={() => setModal({ type: "complete-production", poId, label: "Complete Production" })}>Complete</button>}
 {st === "on_hold" && <button className="btn primary" onClick={() => setModal({ type: "resume-production", poId, label: "Resume Production" })}>Resume</button>}
 {st !== "completed" && st !== "cancelled" && <button className="btn danger" onClick={() => setModal({ type: "cancel-production", poId, label: "Cancel Production" })}>Cancel</button>}
 </div>
 </div>
 );
 }

 // ==================== SCHEDULE ====================
 function ScheduleTab() {
 return (
 <div>
 {scheds.length === 0 ? <div className="empty">No schedules</div> : scheds.map((s, i) => (
 <div className="card" key={i}>
 <div style={{ display: "flex", justifyContent: "space-between" }}><h3>{s.production_order || s.po || "Schedule"}</h3><Badge value={s.status} /></div>
 <div className="meta"><span>Res: {s.production_resource || s.resource || "\u2014"}</span><span>{(s.planned_start || "").substring(0, 10)} \u2192 {(s.planned_end || "").substring(0, 10)}</span><Badge value={s.priority || "medium"} /></div>
 </div>
 ))}
 </div>
 );
 }

 // ==================== INVENTORY ====================
 function InventoryTab() {
 return (
 <div>
 {stocks.length === 0 ? <div className="empty">No inventory</div> : stocks.map((s, i) => (
 <div className="card" key={i}>
 <h3>{s.material_product || s.material || "Stock"}</h3>
 <div className="meta"><span>{s.location || "\u2014"}</span><span>Avail: {s.available_quantity || 0}</span><span>Res: {s.reserved_quantity || 0}</span><span>Tot: {s.total_quantity || 0}</span><Badge value={s.status || "available"} /></div>
 </div>
 ))}
 </div>
 );
 }

 // ==================== ALERTS ====================
 function AlertsTab() {
 return (
 <div>
 {alerts.length === 0 ? <div className="empty">No alerts</div> : alerts.map((a, i) => (
 <div className="card" key={i}>
 <div style={{ display: "flex", justifyContent: "space-between" }}><h3>{a.material_product || a.type || "Alert"}</h3><Badge value={a.severity || a.urgency || "medium"} /></div>
 <div style={{ fontSize: 13, color: "var(--txt2)", marginTop: 4 }}>{a.message || a.description || ""}</div>
 <div className="meta"><span>{a.location || ""}</span><span>{(a.sys_created_on || "").substring(0, 10)}</span></div>
 </div>
 ))}
 </div>
 );
 }

 // ==================== MODAL ====================
 function renderModal() {
 if (!modal) return null;
 let body: React.ReactNode;
 if (modal.type === "issue-material") {
 body = (
 <div>
 <div className="field"><label>Material</label><input value={modal.matName || ""} readOnly /></div>
 <div className="field"><label>Issue Quantity</label><input type="number" min="1" value={qty} onChange={e => setQty(e.target.value)} /></div>
 <div className="btn-row">
 <button className="btn secondary" onClick={() => setModal(null)}>Cancel</button>
 <button className="btn primary" onClick={() => doAction("issue-material", { production_order_id: modal.poId, production_material_id: modal.matId, quantity: parseInt(qty) }, "Issue Material")}>Confirm Issue</button>
 </div>
 </div>
 );
 } else if (modal.type === "record-production") {
 body = (
 <div>
 <div className="field"><label>Produced Quantity</label><input type="number" min="1" value={qty} onChange={e => setQty(e.target.value)} /></div>
 <div className="field"><label>Notes</label><textarea value={notes} onChange={e => setNotes(e.target.value)} /></div>
 <div className="btn-row">
 <button className="btn secondary" onClick={() => setModal(null)}>Cancel</button>
 <button className="btn success" onClick={() => doAction("record-production", { production_order_id: modal.poId, quantity: parseInt(qty), notes }, "Record Production")}>Confirm</button>
 </div>
 </div>
 );
 } else {
 body = (
 <div>
 <p style={{ marginBottom: 16, fontSize: 14 }}>Are you sure you want to {modal.label}?</p>
 <div className="btn-row">
 <button className="btn secondary" onClick={() => setModal(null)}>Cancel</button>
 <button className={`btn ${modal.type === "cancel-production" ? "danger" : "primary"}`} onClick={() => doAction(modal.type, { production_order_id: modal.poId }, modal.label)}>Confirm</button>
 </div>
 </div>
 );
 }
 return (
 <div className="modal-overlay" onClick={e => { if ((e.target as HTMLElement).className === "modal-overlay") setModal(null); }}>
 <div className="modal"><h3>{modal.label}</h3>{body}</div>
 </div>
 );
 }

 // ==================== RENDER ====================
 const TABS = [
 { id: "home", icon: "\uD83C\uDFE0", label: "Home" },
 { id: "orders", icon: "\uD83D\uDCCB", label: "Orders" },
 { id: "schedule", icon: "\uD83D\uDCC5", label: "Schedule" },
 { id: "inventory", icon: "\uD83D\uDCE6", label: "Inventory" },
 { id: "alerts", icon: "\uD83D\uDD14", label: "Alerts" },
 ];

 let tabContent: React.ReactNode;
 if (loading) tabContent = <div className="loading">Loading...</div>;
 else if (tab === "home") tabContent = <HomeTab />;
 else if (tab === "orders") tabContent = <OrdersTab />;
 else if (tab === "schedule") tabContent = <ScheduleTab />;
 else if (tab === "inventory") tabContent = <InventoryTab />;
 else if (tab === "alerts") tabContent = <AlertsTab />;

 return (
 <div className="app">
 <div className="header">
 {sel ? <span className="back" onClick={() => { setSel(null); setMsg(null); }}>{"\u2190"}</span> : null}
 {sel ? "Order Detail" : "\uD83C\uDFED Industrial Production Mobile"}
 </div>
 <div className="content">
 {msg && <div className={`msg ${msg.type}`}>{msg.text}</div>}
 {tabContent}
 </div>
 {!sel && (
 <div className="tabs">
 {TABS.map(t => (
 <div key={t.id} className={`tab${tab === t.id ? " active" : ""}`} onClick={() => switchTab(t.id)}>
 <span className="icon">{t.icon}</span>{t.label}
 </div>
 ))}
 </div>
 )}
 {renderModal()}
 </div>
 );
}
