","*{margin:0;padding:0;box-sizing:border-box}
body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:#f1f3f5;color:#1d1d1d;-webkit-tap-highlight-color:transparent}
:root{--pri:#0b6e99;--ok:#2e7d32;--warn:#e65100;--err:#c62828;--bg:#f1f3f5;--card:#fff;--border:#dee2e6;--txt:#1d1d1d;--txt2:#555;--radius:12px}
.app{display:flex;flex-direction:column;height:100vh;max-width:480px;margin:0 auto;background:var(--bg)}
.header{background:var(--pri);color:#fff;padding:14px 16px;font-size:17px;font-weight:600;display:flex;align-items:center;gap:10px;position:sticky;top:0;z-index:10}
.header .back{font-size:22px;cursor:pointer;padding:4px 8px;border-radius:6px}
.header .back:active{background:rgba(255,255,255,.2)}
.content{flex:1;overflow-y:auto;padding:12px;padding-bottom:80px}
.tabs{position:fixed;bottom:0;left:50%;transform:translateX(-50%);width:100%;max-width:480px;display:flex;background:#fff;border-top:1px solid var(--border);z-index:10}
.tab{flex:1;text-align:center;padding:8px 2px;font-size:11px;color:var(--txt2);cursor:pointer;transition:.15s}
.tab.active{color:var(--pri);font-weight:600}
.tab .icon{font-size:22px;display:block;line-height:1}
.card{background:var(--card);border-radius:var(--radius);padding:14px;margin-bottom:10px;box-shadow:0 1px 3px rgba(0,0,0,.08);cursor:pointer}
.card:active{background:#f8f9fa}
.card h3{font-size:15px;margin-bottom:4px}
.card .meta{font-size:12px;color:var(--txt2);display:flex;flex-wrap:wrap;gap:6px 14px;margin-top:6px}
.badge{display:inline-block;padding:3px 10px;border-radius:20px;font-size:11px;font-weight:600;color:#fff}
.badge.ok{background:var(--ok)}.badge.warn{background:var(--warn)}.badge.err{background:var(--err)}.badge.info{background:var(--pri)}.badge.gray{background:#868e96}
.stat-row{display:flex;gap:10px;margin-bottom:10px}
.stat{flex:1;background:var(--card);border-radius:var(--radius);padding:14px;text-align:center;box-shadow:0 1px 3px rgba(0,0,0,.08)}
.stat .val{font-size:28px;font-weight:700;color:var(--pri)}
.stat .lbl{font-size:11px;color:var(--txt2);margin-top:2px}
.detail-section{background:var(--card);border-radius:var(--radius);padding:14px;margin-bottom:10px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
.detail-section h4{font-size:14px;font-weight:600;margin-bottom:10px;color:var(--pri)}
.detail-row{display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid #f1f3f5;font-size:13px}
.detail-row:last-child{border:none}
.detail-row .label{color:var(--txt2)}
.detail-row .value{font-weight:500;text-align:right;max-width:60%}
.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}
.btn{padding:12px 18px;border:none;border-radius:10px;font-size:14px;font-weight:600;cursor:pointer;flex:1;min-width:120px;text-align:center;transition:.15s}
.btn:active{transform:scale(.97)}
.btn.primary{background:var(--pri);color:#fff}
.btn.success{background:var(--ok);color:#fff}
.btn.danger{background:var(--err);color:#fff}
.btn.secondary{background:#e9ecef;color:var(--txt)}
.btn:disabled{opacity:.5}
.modal-overlay{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:100;display:flex;align-items:flex-end;justify-content:center}
.modal{background:#fff;border-radius:16px 16px 0 0;padding:20px;width:100%;max-width:480px;max-height:80vh;overflow-y:auto}
.modal h3{font-size:17px;margin-bottom:14px}
.modal .field{margin-bottom:12px}
.modal .field label{display:block;font-size:12px;color:var(--txt2);margin-bottom:4px}
.modal .field input,.modal .field textarea{width:100%;padding:12px;border:1px solid var(--border);border-radius:8px;font-size:15px}
.modal .field textarea{min-height:60px;resize:vertical}
.modal .btn-row{display:flex;gap:8px;margin-top:16px}
.msg{padding:12px;border-radius:8px;margin-bottom:10px;font-size:13px;font-weight:500}
.msg.ok{background:#e8f5e9;color:var(--ok)}.msg.err{background:#ffebee;color:var(--err)}
.loading{text-align:center;padding:40px;color:var(--txt2)}
.empty{text-align:center;padding:40px;color:var(--txt2)}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React from "react";
import ReactDOM from "react-dom/client";
import App from "./app";

